let DATA=[],CATALOG=[];let part=0,limit=15,selected=[];const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const colors=['#3e4d3b','#3b284a','#8b492d','#263d50','#68614b','#3b5255'];let shown=[];function render(){let q=$('#search').value.toLocaleLowerCase();let arr=DATA.filter(d=>(!part||d.part===part)&&d.title.toLocaleLowerCase().includes(q));if($('#sort').value==='az')arr.sort((a,b)=>a.title.localeCompare(b.title));$('#count').textContent=arr.length+' bài đọc'+(part?' · Passage '+part:'');shown=arr.slice(0,limit);let cols=innerWidth<=560?2:innerWidth<=900?3:5;$('#books').innerHTML='';for(let i=0;i<shown.length;i+=cols){let shelf=document.createElement('div');shelf.className='shelf';shelf.innerHTML=shown.slice(i,i+cols).map((d,j)=>`<button class="book" style="--color:${colors[(i+j)%colors.length]}" data-id="${esc(d.id)}" aria-label="Xem ${esc(d.title)}"><span class="spine"><span>${esc(d.title)}</span></span><span class="book-top"></span><span class="book-bottom"></span><span class="book-edge"></span><span class="front">${d.image?`<img src="${d.image}" alt="" loading="lazy">`:''}<span class="shade"></span><span class="booktext"><span class="part">Passage ${d.part}</span><h2>${esc(d.title)}</h2><span class="types">${d.types.map(esc).join('<br>')}</span></span></span></button>`).join('');$('#books').append(shelf)}if(!arr.length)$('#books').innerHTML='<div class="empty">Không tìm thấy bài đọc. Hãy thử tên khác.</div>';$('#more').hidden=arr.length<=limit;document.querySelectorAll('.book').forEach(b=>b.onclick=()=>openLesson(b.dataset.id))}function openLesson(id){let d=DATA.find(x=>x.id===id);$('#detail').innerHTML=`<div class="detail">${d.image?`<img src="${d.image}" alt="${esc(d.cover?.alt||'')}">`:''}<div><span class="part">Passage ${d.part} · ${d.count} câu</span><h2>${esc(d.title)}</h2><p>${d.types.map(esc).join('<br>')}</p><div class="actions"><a class="button primary" href="${esc(d.url)}" target="_blank" rel="noopener">Vào làm bài ↗</a></div></div></div><p class="notice"></p>`;$('#lesson').showModal()}document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{part=+b.dataset.part;limit=15;document.querySelectorAll('[data-part]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#search').oninput=()=>{limit=15;render()};$('#sort').onchange=render;$('#more').onclick=()=>{limit+=15;render()};document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));function random(){try{selected=FullTestCore.select(CATALOG,localStorage);$('#testbody').innerHTML=selected.map(d=>`<div class="selected"><b>Passage ${d.part}</b><br>${esc(d.title)}</div>`).join('')+'<div class="actions"><button id="again">Chọn ngẫu nhiên lại</button></div>';$('#again').onclick=random;$('#random').classList.add('primary');$('#manual').classList.remove('primary');$('#test-status').textContent='Ưu tiên bài chưa làm. Bộ đề gồm 40 câu.'}catch{$('#test-status').textContent='Chưa tải được đủ bài. Vui lòng thử lại.'}}
function manual(){$('#manual').classList.add('primary');$('#random').classList.remove('primary');$('#testbody').innerHTML='<div class="pick">'+[1,2,3].map(p=>`<label for="p${p}">Passage ${p}</label><select id="p${p}">${CATALOG.filter(d=>d.part===p&&d.count===(p===3?14:13)).sort((a,b)=>a.title.localeCompare(b.title)).map(d=>`<option value="${esc(d.id)}">${esc(d.title)}</option>`).join('')}</select>`).join('')+'</div>';function update(){selected=[1,2,3].map(p=>CATALOG.find(d=>d.id===$('#p'+p).value));$('#test-status').textContent='Đã chọn 3 passages, 40 câu.'}document.querySelectorAll('.pick select').forEach(s=>s.onchange=update);update()}
$('#start-test').onclick=()=>{try{const ids=selected.map(d=>d.id);FullTestCore.manual(CATALOG,ids);location.href='full-test.html?'+new URLSearchParams({mode:'manual',p1:ids[0],p2:ids[1],p3:ids[2]})}catch{$('#test-status').textContent='Hãy chọn đủ 3 passages hợp lệ.'}};
$('#random').onclick=random;$('#manual').onclick=manual;$('#full').onclick=()=>{random();$('#test').showModal()};let prevCols=0;window.addEventListener('resize',()=>{let c=innerWidth<=560?2:innerWidth<=900?3:5;if(c!==prevCols){prevCols=c;render()}});render();
async function boot(){try{const [response,overrides]=await Promise.all([fetch('lesson-catalog.json',{cache:'no-cache'}),fetch('cover-overrides.json',{cache:'no-cache'}).then(r=>r.ok?r.json():{}).catch(()=>({}))]);if(!response.ok)throw Error();CATALOG=await response.json();DATA=CATALOG.map(d=>({...d,cover:overrides[d.id]||d.cover,image:(overrides[d.id]||d.cover)?.asset,url:'exam.html?lesson='+encodeURIComponent(d.id)}));for(const [i,card]of [...document.querySelectorAll('#legacy-source article')].entries()){const link=card.querySelector('.open-lesson'),url=link.getAttribute('href'),cover=overrides[url];DATA.push({id:'legacy-'+i,title:card.querySelector('h3').textContent,part:+card.dataset.part,count:+card.dataset.part===3?14:13,types:card.querySelector('.meta').textContent.split(' — '),image:cover?.asset||card.querySelector('img').getAttribute('src'),cover:cover||{alt:card.querySelector('img').alt},url})}const preferred=['sunlight soap','ancient greek','olympic torch','forgotten forest','spinning jenny','movement underwater','roller coaster','tikopia','voynich','green roofs'];const rank=d=>{const n=preferred.findIndex(s=>d.title.toLowerCase().includes(s));return n<0?100:n};DATA.sort((a,b)=>rank(a)-rank(b)||a.title.localeCompare(b.title));$('#load-status').textContent='';$('#start-test').disabled=false;render();try{const draft=JSON.parse(localStorage.getItem('ielts-full-test-draft')||'null');if(draft&&!draft.submitted){const resume=document.createElement('a');resume.className='button';resume.href='full-test.html?resume=1';resume.textContent='Tiếp tục bộ đề';document.querySelector('header').append(resume)}}catch{}}catch{$('#load-status').textContent='Không tải được kho bài. Vui lòng tải lại trang.'}}
$('#start-test').disabled=true;boot();
